    frame_w = next((c for c,v in enumerate(grid[0]) if v != base), len(grid[0]))
    if frame_w == 0: frame_w = 5
    sprite_c0 = frame_w + 1
    separators = [r for r in range(h) if all(grid[r][c] == base for c in range(frame_w))]
    # Pair each panel bounded by separator rows with its neighboring sprite.
    panels=[]
    for i,top in enumerate(separators):
        end = separators[i+1] if i+1 < len(separators) else h
        if end-top <= 1: continue
        cells={(r-top-1,c-1) for r in range(top+1,end)
               for c in range(1,frame_w-1) if grid[r][c] == 0}
        if cells: panels.append((top,cells,end))
    sprites=[]
    for i,top in enumerate(separators):
        end = separators[i+1] if i+1 < len(separators) else h
        colors={grid[r][c] for r in range(top+1,end) for c in range(sprite_c0,w) if grid[r][c] != 0}
        for color in colors:
            shape={(r-top-1,c-sprite_c0) for r in range(top+1,end)
